const Q=[...SA.map(q=>({s:0,t:q[0],o:q.slice(1).map((x,j)=>[x,j])})),...RQ.map(q=>({s:1,t:q[0],o:q.slice(1)})),...LQ.map(q=>({s:2,t:q[0],o:q.slice(1).map((x,j)=>[x,j])}))];
