function result(a){const sa=Q.map((q,i)=>q.s===0?a[i]:null).filter(x=>x!=null),mean=sa.reduce((p,n)=>p+n,0)/sa.length,st=Math.round(mean),edge=Math.abs(mean-st)>=.35?(mean>st?ST[Math.min(4,st+1)]:ST[Math.max(0,st-1)]):null;
 const cnt=Array(11).fill(0),app=Array(11).fill(0);Q.forEach((q,i)=>{if(q.s===1){q.o.forEach(o=>app[o[1]]++);cnt[a[i]]++}});
 const rk=RN.map((n,i)=>[app[i]?cnt[i]/app[i]:0,i]).sort((x,y)=>y[0]-x[0]||x[1]-y[1]),tie=rk[0][0]===rk[1][0];
 const L=Q.map((q,i)=>q.s===2?a[i]:null).filter(x=>x!=null),pt=QL.map((l,k)=>l?"Someone who "+l[L[k]]+".":null).filter(Boolean);
 return `<h1>Your reading begins</h1><p class="mute">Everything below comes from your own answers.</p>
<h2>Your soul’s age</h2><div class="card"><div class="track" aria-hidden="true">${ST.map((n,i)=>`<b style="left:${i*25}%">${n}</b>`).join("")}<i style="left:${mean/4*100}%"></i></div><h3>${ST[st]} soul${edge?`, leaning toward ${edge}`:""}</h3><p>${SD[st]}</p><p class="mute">A symbolic idea, not a ranking. Older isn’t better, and every stage has gifts.</p></div>
<h2>Your spiritual role</h2><div class="card">${rk.slice(0,3).map(([v,i],k)=>`<div class="role"><span aria-hidden="true">${RE[i]}</span><div><b>${RN[i]}</b>${k===0?" · strongest":""}<br>${RR[i]}</div></div>`).join("")}${tie?`<p class="mute">Your top two were tied, so weigh them equally.</p>`:""}</div>
<h2>Your soulmate portrait</h2><div class="card"><h3>The ${AD[L[3]]} ${NO[L[0]]}</h3><ul>${pt.slice(0,3).map(x=>`<li>${x}</li>`).join("")}</ul><p class="mute">${pt.length-3} more qualities, the challenges to watch for and questions to ask when dating are in your full report. This describes what may suit you, not a destined person.</p></div>
<h2>Your past-life echoes</h2><div class="card">${rk.slice(0,3).map(([v,i])=>`<div class="role"><span aria-hidden="true">${RE[i]}</span><div>In another life you may have been ${PL[i]}.</div></div>`).join("")}<p class="mute">Just for fun and reflection. Past lives can’t be proven, and these echoes come only from your answers.</p></div>
<h2>Your complete reading</h2>
`}
