const LP={1:["independence and new beginnings","starting what others only imagine","self-reliance turning into isolation"],2:["partnership and sensitivity","reading a room and building trust","holding back needs to keep the peace"],3:["expression and play","bringing ideas and people to life","scattered energy leaving projects unfinished"],4:["structure and steadiness","turning plans into dependable results","rigidity when plans change"],5:["change and freedom","adapting quickly and learning by doing","restlessness undercutting commitment"],6:["care and responsibility","creating warmth and belonging","over-giving turning into quiet resentment"],7:["inquiry and inner life","noticing subtle patterns","withdrawal that feels like distance to others"],8:["ambition and stewardship","directing resources toward real goals","tying self-worth to achievement"],9:["compassion and completion","seeing the wider human picture","struggling to let finished things go"],11:["intuition and illumination (a master number)","inspiring through sensitivity and insight","intensity tipping into anxiety"],22:["vision made practical (a master number)","building things that serve many people","pressure to live up to big ideas"],33:["compassionate teaching (a master number)","lifting others through patient care","carrying everyone else’s load"]};
