 app.innerHTML=`<div class="auth">${ico(6)}<h1>${esc(s.name)}, your free reading is ready</h1><p class="mute">Enter your email to see it.</p><form id="f" class="card"><label>Email<input id="em" type="email" required autocomplete="email"></label><button class="btn full">Show my free reading</button><div id="m"></div></form><p class="mute small">We use your email as described in our <a href="/#/privacy">Privacy Policy</a>.</p></div>`;
